INSERT INTO "activities" ("title", "slug", "body", "day", "time", "price", "age_range", "contact", "phone", "external_url", "hero_image_path", "hero_image_alt", "source_url", "source_updated_on", "draft", "position")
VALUES
  ('1st Spencers Wood Brownies', '1st-spencers-wood-brownies', 'Brownies is about trying new things that teach girls aged 7 to 10 about themselves, their community and their world. Brownies introduces girls to a world of new opportunities, challenges and fun. Girls go along to camps, holidays, day trips and sleepovers. They get together with friends at regular meetings where they learn new hobbies, get creative, explore other cultures and have outdoor adventures.

For more information, visit [Girlguiding](https://www.girlguiding.org.uk/).', 'Friday', '6:00 PM - 7:30 PM', '£30 per term & £15 joining fee', '7-10', NULL, NULL, NULL, '/images/activities/1st-spencers-wood-brownies.png', '1st Spencers Wood Brownies', 'https://spencerswoodvillagehall.co.uk/regular-activities/1st-spencers-wood-brownies', '2026-08-25', false, 0),
  ('1st Spencers Wood Guides', '1st-spencers-wood-guides', 'Come and join 1st Spencers Wood Guides at Spencers Wood Village Hall.', 'Wednesday', '7:30 PM - 9:00 PM', NULL, NULL, 'spencerswoodguides@hotmail.co.uk', NULL, NULL, '/images/activities/1st-spencers-wood-guides.png', '1st Spencers Wood Guides', 'https://spencerswoodvillagehall.co.uk/regular-activities/1st-spencers-wood-guides', '2026-08-25', false, 2),
  ('2nd Spencers Wood Brownies', '2nd-spencers-wood-brownies', 'Brownies is about trying new things that teach girls aged 7 to 10 about themselves, their community and their world. Being a Brownie is all about fun, friendship and adventure.

For more information, visit [Girlguiding](https://www.girlguiding.org.uk/).', 'Wednesday', '6:00 PM - 7:30 PM', NULL, '7-10', NULL, NULL, NULL, '/images/activities/2nd-spencers-wood-brownies.png', '2nd Spencers Wood Brownies', 'https://spencerswoodvillagehall.co.uk/regular-activities/2nd-spencers-wood-brownies', NULL, false, 1),
  ('Art Group', 'art-group', 'Come and join Art Group at Spencers Wood Village Hall.', 'Thursday', '2:15 PM - 4:45 PM', '£3', NULL, NULL, NULL, NULL, '/images/activities/art-group.jpg', 'Art Group', 'https://spencerswoodvillagehall.co.uk/regular-activities/art-group', NULL, false, 3),
  ('Baby and Toddler Group', 'baby-and-toddler-group', 'Spencers Wood baby and toddler group offers twice-weekly free play sessions for all preschool-age children accompanied by parents or carers. Everyone is welcome. We are run by volunteers and are not-for-profit.

Sessions run Mondays and Thursdays during term time, except bank holidays. You do not need to book a place; it is a drop-in session. The cost is £3 cash per session per family.', 'Monday, Thursday', '9:45 AM - 11:45 AM', '£3', NULL, NULL, NULL, NULL, NULL, NULL, 'https://spencerswoodvillagehall.co.uk/regular-activities/baby-and-toddler-group', NULL, false, 4),
  ('Badminton Club', 'badminton-club', 'This long-established club welcomes new members. If you are interested in having fun in a friendly atmosphere and playing social badminton, come along on a Thursday night and try it out. Members are of all ages and abilities.', 'Thursday', '8:00 PM - 10:00 PM', 'Annual membership fee', NULL, NULL, NULL, NULL, '/images/activities/badminton-club.jpg', 'Badminton Club', 'https://spencerswoodvillagehall.co.uk/regular-activities/badminton-club', NULL, false, 5),
  ('Berzerk Productions', 'berzerk-productions', 'Berzerk Productions is a multi-award-winning drama coaching company in Reading. We provide private drama classes in Spencers Wood for students aged 4 to 19 and cater for all abilities.

Our workshops build self-development, self-esteem and confidence alongside acting and drama skills. For more information, visit [Berzerk Productions](https://www.berzerkproductions.com).', 'Monday', '4:30 PM - 6:30 PM', 'Varies', '4-19', NULL, NULL, 'https://www.berzerkproductions.com', '/images/activities/berzerk-productions.jpg', 'Berzerk Productions', 'https://spencerswoodvillagehall.co.uk/regular-activities/berzerk-productions', NULL, false, 6),
  ('Bloom Baby Busy Bees', 'bloom-baby-busy-bees', 'For babies from six months to toddling. This fun, interactive musical development class focuses on growing confidence, fine and gross motor skills, language development, songs, activities and Makaton signing.

For more information, visit [Bloom Baby](https://bloombabyclasses.com/readingandwokingham).', 'Wednesday', '10:00 AM - 10:45 AM', NULL, NULL, NULL, NULL, 'https://bloombabyclasses.com/readingandwokingham', '/images/activities/bloom-baby-busy-bees.jpg', 'Bloom Baby Busy Bees', 'https://spencerswoodvillagehall.co.uk/regular-activities/bloom-baby-busy-bees', NULL, false, 8),
  ('Bloom Baby', 'bloom-baby', 'A gentle baby development class focused on bonding with your little one. The class uses bubbles, parachutes, lights, songs, pompoms, tummy time and baby development moves, ending with a relaxing massage.

For more information, visit [Bloom Baby](https://bloombabyclasses.com/readingandwokingham).', 'Wednesday', '11:10 AM - 11:55 AM', NULL, NULL, NULL, NULL, 'https://bloombabyclasses.com/readingandwokingham', '/images/activities/bloom-baby.jpg', 'Bloom Baby', 'https://spencerswoodvillagehall.co.uk/regular-activities/bloom-baby', NULL, false, 7),
  ('Board Games', 'board-games', 'Meet new people, or hang out with friends, and play more games. Bring your own games or choose from the growing collection. Any tabletop games are welcome, and you can also come along to watch or paint miniatures.', 'Tuesday', '7:30 PM - 10:30 PM', '£5', NULL, NULL, NULL, 'https://www.facebook.com/groups/768570547487169', '/images/activities/board-games.jpg', 'Board Games', 'https://spencerswoodvillagehall.co.uk/regular-activities/board-games', NULL, false, 9),
  ('Calming Space Relaxation and Sound Immersion', 'calming-space-relaxation-and-sound-immersion', 'Come and join Calming Space Relaxation and Sound Immersion at Spencers Wood Village Hall.', 'Last Friday of month', '8:15 PM - 9:15 PM', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://spencerswoodvillagehall.co.uk/regular-activities/calming-space-relaxation-and-sound-immersion', NULL, false, 10),
  ('Clubbercise', 'clubbercise', '£7 pre-paid online and £7.50 paid on the door by cash or bank transfer. Reusable glow sticks are an additional £6. Book via Clubbercise with Leah on Facebook or Instagram.', 'Thursday', '7:00 PM - 7:45 PM', '£7 pre-paid online; £7.50 on the door', NULL, NULL, NULL, NULL, '/images/activities/clubbercise.png', 'Clubbercise', 'https://spencerswoodvillagehall.co.uk/regular-activities/clubbercise', NULL, false, 11),
  ('Community Craft Group', 'community-craft-group', 'A group for people of all skill levels and ages to have a cup of tea, chat and craft. Hand sewing, knitting, crochet, cross stitch, diamond dotz, card making and quilting are all welcome.', 'Monday', '7:30 PM - 9:30 PM', '£2', NULL, NULL, NULL, 'https://www.facebook.com/groups/1012742509535986', '/images/activities/community-craft-group.jpg', 'Community Craft Group', 'https://spencerswoodvillagehall.co.uk/regular-activities/community-craft-group', NULL, false, 12),
  ('Kyushindo Karate Club', 'kyushindo-karate-club', 'Looking to try something new, get fit, make friends, learn a skill and gain confidence? Kyushindo Karate trains every Monday night. No experience is required.

We blend traditional and modern martial arts approaches to develop physical abilities, self-defence capabilities and mental resilience. Your first lesson is free.', 'Monday', '7:30 PM - 9:00 PM', '£4.50 per class / £25 annual membership', '13 to adult', 'reading.kyushindo@gmail.com', NULL, NULL, '/images/activities/kyushindo-karate-club.jpg', 'Kyushindo Karate Club', 'https://spencerswoodvillagehall.co.uk/regular-activities/kyushindo-karate-club', NULL, false, 13),
  ('Ladies Only Boxercise', 'ladies-only-boxercise', 'Come and join Ladies Only Boxercise at Spencers Wood Village Hall. Find us on Instagram at @ladies_only_boxercise.', 'Tuesday', '8:00 PM - 9:00 PM', '£7', NULL, NULL, NULL, NULL, '/images/activities/ladies-only-boxercise.jpg', 'Ladies Only Boxercise', 'https://spencerswoodvillagehall.co.uk/regular-activities/ladies-only-boxercise', NULL, false, 14),
  ('Over 50s Exercise', 'over-50s-exercise', 'Come and join Over 50''s Exercise at Spencers Wood Village Hall.', 'Friday', '10:00 AM - 10:45 AM', NULL, NULL, NULL, NULL, NULL, '/images/activities/over-50s-exercise.png', 'Over 50s Exercise', 'https://spencerswoodvillagehall.co.uk/regular-activities/over-50s-exercise', NULL, false, 15),
  ('Repair Cafe', 'repair-cafe', 'Spencers Wood Repair Cafe is a friendly group of expert volunteers running a monthly session at the Village Hall. We try to repair household items that might otherwise be destined for landfill. Donations are appreciated.', '1st Sunday of month', '10:00 AM - 1:00 PM', 'Free', NULL, NULL, NULL, 'https://www.facebook.com/groups/453985379084488/', NULL, NULL, 'https://spencerswoodvillagehall.co.uk/regular-activities/repair-cafe', NULL, false, 16),
  ('Spencers Wood Market', 'spencers-wood-market', 'Spencers Wood Market takes place every 3rd Sunday of the month from 10 am to 1 pm at the Village Hall. Free entry.', '3rd Sunday of month', '10:00 AM - 1:00 PM', 'Free', NULL, NULL, NULL, 'https://www.facebook.com/Spencers.Wood.Marketuk', NULL, NULL, 'https://spencerswoodvillagehall.co.uk/regular-activities/spencers-wood-market', NULL, false, 17),
  ('Yoga with Tash', 'yoga-with-tash', 'Takes place on Tuesdays from 12 to 1 pm. Please visit [Yoga with Tash](https://www.yogawithtash.com) to book your slot.', 'Tuesday', '12:00 PM - 1:00 PM', NULL, NULL, NULL, NULL, 'https://www.yogawithtash.com', '/images/activities/yoga-with-tash.jpg', 'Yoga with Tash', 'https://spencerswoodvillagehall.co.uk/regular-activities/yoga-with-tash', NULL, false, 18)
ON CONFLICT ("slug") DO NOTHING;
